using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
internal static class RadialMigrationTests
{
 static readonly int[] Starts={59,117,175,234,292}, Splits={117,175,234,292,350};
 static readonly double[] Phases={388.45804322619875,200.26737946506537,294.7849322760851,300.55904733072225,113.36460065894282}, Angles={0,10,-10,20,-20}, Speeds={6,5,5,4,4};
 static int checks,states; static double maxPosition,maxDirection;
 static void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
 static double Delta(double a,double b){return Math.Abs((a-b)%360+540)%360-180;}
 static double AngleError(double a,double b){return Math.Abs(((a-b)%360+540)%360-180);}
 static void Near(double a,double b,double eps,string message){Check(Math.Abs(a-b)<=eps,message+": "+a+" / "+b);}
 static EditorState Load(string file){var s=Json.Read<EditorState>(File.ReadAllText(file));Motion.Normalize(s);return s;}
 static EditorState Opening(EditorState state){var s=state.Snapshot();s.tracks=s.tracks.Where(t=>t.id.StartsWith("wave_")||t.id.StartsWith("opening_radial_")||t.id=="transition"||t.targetTag=="pre_transition").ToList();s.duration=950;Motion.Normalize(s);return s;}
 static string Semantic(SimBullet b,bool candidate){
  if(!candidate){var parts=b.source.id.Split('_');int wave=int.Parse(parts[1])-1;return wave+"|"+(parts[2]=="ring"?-1:int.Parse(parts[2].Substring(3)))+"|"+b.index;}
  int w,f,slot;if(b.source.id.StartsWith("wave_")){w=int.Parse(b.source.id.Split('_')[1])-1;f=-1;slot=((int)Math.Round((b.direction-Phases[w])/36)%10+10)%10;}
  else {w=Array.IndexOf(Splits,b.birth);Check(w>=0,"Unexpected fan birth "+b.birth);f=b.index;slot=((int)Math.Round((b.direction-Phases[w]-180-Angles[f])/36)%10+10)%10;}
  return w+"|"+f+"|"+slot;
 }
 static bool Relevant(SimBullet b){return !b.dead&&b.source.tag=="pre_transition";}
 static Dictionary<string,SimBullet> Rows(BulletWorld world,bool candidate){return world.bullets.Where(Relevant).ToDictionary(b=>Semantic(b,candidate));}
 static string Signature(BulletWorld w){return Json.Write(w.bullets.Where(Relevant).Select(b=>new{b.x,b.y,b.birth,b.index,b.speed,b.direction,b.alpha,b.collision,b.life,source=b.source.id}).OrderBy(b=>b.source).ThenBy(b=>b.birth).ThenBy(b=>b.direction).ThenBy(b=>b.index).ToArray());}
 static void Compare(EditorState before,EditorState after){var a=new BulletWorld(before);var b=new BulletWorld(after);for(int frame=0;frame<=894;frame++){a.Seek(frame);b.Seek(frame);var aa=Rows(a,false);var bb=Rows(b,true);Check(aa.Count==bb.Count,"Count frame "+frame+": "+aa.Count+"/"+bb.Count);foreach(var row in aa){Check(bb.ContainsKey(row.Key),"Missing "+frame+"/"+row.Key);var x=row.Value;var y=bb[row.Key];states++;double error=Math.Max(Math.Abs(x.x-y.x),Math.Abs(x.y-y.y));maxPosition=Math.Max(maxPosition,error);Near(x.x,y.x,.003,"X "+frame+"/"+row.Key);Near(x.y,y.y,.003,"Y "+frame+"/"+row.Key);Near(x.alpha,y.alpha,1e-12,"Alpha "+frame);Near(x.scale,y.scale,1e-12,"Scale "+frame);Near(DrawingDepth.Bullet(x),DrawingDepth.Bullet(y),1e-12,"Depth "+frame+"/"+row.Key);Check(x.collision==y.collision,"Collision "+frame);Check(x.color.ToArgb()==y.color.ToArgb(),"Color "+frame);Check((x.sprite??x.source.sprite)==(y.sprite??y.source.sprite),"Sprite "+frame);Near(BulletWorld.BulletAngle(x,x.direction),BulletWorld.BulletAngle(y,y.direction),1e-9,"Sprite angle "+frame);if(!row.Key.Contains("|-1|")){double de=AngleError(x.direction,y.direction);maxDirection=Math.Max(maxDirection,de);Check(de<.0001,"Direction "+frame+"/"+row.Key+": "+de);Near(x.speed,y.speed,1e-12,"Fan speed");Check(x.birth==y.birth&&x.life==y.life,"Fan birth/life "+frame+"/"+row.Key+": "+x.life+"/"+y.life);}}}
 }
 static void Edits(EditorState scene){foreach(int sectors in new[]{1,7,12})foreach(int speedFactor in new[]{1,2})foreach(int delay in new[]{0,10}){var s=scene.Snapshot();foreach(var t in s.tracks.Where(t=>t.id.StartsWith("wave_")&&!t.templateOnly)){if(t.kind=="group"){t.spawnActions[0].copyCount=sectors;Motion.EditValue(t,"x",0,413);Motion.EditValue(t,"y",0,283);Motion.EditValue(t,"angle",0,t.angle+37);}else if(t.id.EndsWith("ring"))Motion.EditValue(t,"speed",0,10*speedFactor);}foreach(var t in s.tracks.Where(t=>t.id.StartsWith("wave_")&&t.kind=="emitter"))foreach(var a in t.bulletActions.Where(a=>a.type=="spawn"))a.start+=delay;var splits=Splits.Select(f=>f+delay).ToArray();Motion.Normalize(s);var w=new BulletWorld(s);foreach(int frame in new[]{59,60,116,117,118,174,175,176,233,234,235,291,292,293,349,350,351,620,730,873}.Concat(splits.SelectMany(f=>new[]{f-1,f,f+1})).Distinct().OrderBy(f=>f)){w.Seek(frame);var actual=w.bullets.Where(Relevant).ToArray();var expected=new List<Tuple<double,double>>();for(int wave=0;wave<5;wave++){if(frame<Starts[wave])continue;for(int slot=0;slot<sectors;slot++){double dir=Phases[wave]+37+360.0*slot/sectors;int age=Math.Min(frame,splits[wave])-Starts[wave];double r=140*speedFactor*(1-Math.Pow(14.0/15,age)),x=413+r*Math.Cos(dir*Math.PI/180),y=283-r*Math.Sin(dir*Math.PI/180);if(frame<splits[wave])expected.Add(Tuple.Create(x,y));else for(int fan=0;fan<5;fan++){double d=(dir+180+Angles[fan])*Math.PI/180,travel=Speeds[fan]*(frame-splits[wave]);expected.Add(Tuple.Create(x+travel*Math.Cos(d),y-travel*Math.Sin(d)));}}}Check(actual.Length==expected.Count,"Edited count "+sectors+" "+frame);var remaining=actual.ToList();foreach(var p in expected){var found=remaining.OrderBy(v=>(v.x-p.Item1)*(v.x-p.Item1)+(v.y-p.Item2)*(v.y-p.Item2)).First();Near(found.x,p.Item1,.003,"Edited X");Near(found.y,p.Item2,.003,"Edited Y");remaining.Remove(found);}}}
 }
 static void Persistence(EditorState s){var w=new BulletWorld(s);w.Seek(730);string expected=Signature(w);foreach(int frame in new[]{117,700,59,729,400,0,730})w.Seek(frame);Check(Signature(w)==expected,"Reverse seek/checkpoint mismatch");var saved=Json.Read<EditorState>(Json.Write(s));Motion.Normalize(saved);var reopened=new BulletWorld(saved);reopened.Seek(730);Check(Signature(reopened)==expected,"Save/reopen mismatch");var history=new UndoHistory();history.Undo.Push(new UndoEntry(new UndoSnapshot{state=s}));var group=s.tracks.First(t=>t.id=="wave_1");Motion.EditValue(group,"x",730,group.x+20);Check(group.keyframes.Count==0,"Center edit baked key");history.Redo.Push(new UndoEntry(new UndoSnapshot{state=s}));var restored=history.Undo.Pop().Restore().state;Motion.Normalize(restored);var undo=new BulletWorld(restored);undo.Seek(730);Check(Signature(undo)==expected,"Undo mismatch");Check(history.Redo.Pop().Restore().state.tracks.First(t=>t.id=="wave_1").x==420,"Redo lost center edit");}
 public static int Main(string[] args){try{var before=Opening(Load(args[0]));var after=Opening(Load(args[1]));Compare(before,after);Edits(after);Persistence(after);var result=new{status="pass",frames=895,states,checks,maxPosition,maxDirection,variants=12,reverseSeek=true,saveReopen=true,undoRedo=true,nativeGameMaker=false};File.WriteAllText(args[2],Json.Write(result));Console.WriteLine(Json.Write(result));return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
